// Checks the requested slot against ALL active appointments (any caller).
const newData = $('Prepare Appointment Data').first().json;
const digits = v => String(v ?? '').replace(/\D/g, '');
const samePhone = (a, b) => { a = digits(a); b = digits(b); return a.length >= 7 && b.length >= 7 && a.slice(-10) === b.slice(-10); };
const normTime = t => {
  const s = String(t ?? '').trim().toLowerCase().replace(/\./g, '');
  const m = s.match(/^(\d{1,2})(?::(\d{2}))?(?::\d{2})?\s*(am|pm)?$/);
  if (!m) return s;
  let h = parseInt(m[1], 10); const min = m[2] || '00';
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  return String(h).padStart(2, '0') + ':' + min;
};
const splitDT = dt => { const s = String(dt ?? '').trim().replace(/\s+/g, ' '); const i = s.indexOf(' '); return i === -1 ? [s, ''] : [s.slice(0, i), s.slice(i + 1)]; };
const slotKey = (d, t) => String(d ?? '').trim() + ' ' + normTime(t);
const inactive = s => ['cancelled', 'canceled', 'rescheduled'].includes(String(s ?? '').toLowerCase().trim());

const newSlot = slotKey(newData.appointment_date, newData.appointment_time);
const rows = $input.all().map(i => i.json).filter(r => r && (r.id || r.datetime));
const clash = rows.find(r => { if (inactive(r.status)) return false; const [d, t] = splitDT(r.datetime); return slotKey(d, t) === newSlot; });

if (!clash) return [{ json: { blocked: false } }];

if (samePhone(clash.phone, newData.phone_number)) {
  return [{ json: { blocked: true, same_caller: true, existing_appointment_id: clash.id || '', message: 'You already have an appointment booked for that date and time.' } }];
}
return [{ json: { blocked: true, same_caller: false, existing_appointment_id: '', reason: 'slot_taken', message: 'Sorry, that time slot is already taken. Could you choose a different time?' } }];

const hoursRows = $('Get Hours').all().map(item => item.json);
const holidayRows = $('Get Holidays').all().map(item => item.json);

const businessTZ = "America/New_York";
const now = new Date(new Date().toLocaleString("en-US", { timeZone: businessTZ }));

const todayDateStr = now.getFullYear() + "-" +
  String(now.getMonth() + 1).padStart(2, "0") + "-" +
  String(now.getDate()).padStart(2, "0");

const dayNames = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
const todayName = dayNames[now.getDay()];

const holidayToday = holidayRows.find(h => h.date === todayDateStr);

let isOpen = false;
let reason = "";
let todaysHours = "N/A";

if (holidayToday && String(holidayToday.closed_all_day).toUpperCase() === "TRUE") {
  isOpen = false;
  reason = "Closed for holiday: " + holidayToday.name;
  todaysHours = "Closed (Holiday)";
} else {
  const todayRow = hoursRows.find(r => r.day === todayName);

  if (!todayRow || todayRow.open === "Closed" || todayRow.close === "Closed") {
    isOpen = false;
    reason = "Closed today";
  } else {
    let openStr = todayRow.open;
    let closeStr = todayRow.close;

    if (holidayToday && holidayToday.open && holidayToday.close) {
      openStr = holidayToday.open;
      closeStr = holidayToday.close;
      reason = "Holiday hours (" + holidayToday.name + ")";
    }

    const currentMinutes = now.getHours() * 60 + now.getMinutes();
    const [openH, openM] = openStr.split(":").map(Number);
    const [closeH, closeM] = closeStr.split(":").map(Number);
    const openMinutes = openH * 60 + openM;
    const closeMinutes = closeH * 60 + closeM;

    isOpen = currentMinutes >= openMinutes && currentMinutes < closeMinutes;
    if (!reason) reason = isOpen ? "Within business hours" : "Outside business hours";
    todaysHours = openStr + " - " + closeStr;
  }
}

return [{
  json: {
    is_open: isOpen,
    today: todayName,
    current_time: now.toTimeString().slice(0,5),
    reason: reason,
    todays_hours: todaysHours,
    is_holiday: !!holidayToday
  }
}];

