// Matches appointments and tickets by phone digits (works with or without +country code) or by reference ID.
const inp = $('Normalize Input').first().json;
const digits = v => String(v ?? '').replace(/\D/g, '');
const phone = digits(inp.phone_number);
const ref = String(inp.reference_id || '').trim().toLowerCase();
const idOf = r => String(r.id || r.ticket_id || '').trim().toLowerCase();
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);

const matches = rows.filter(r => {
  if (ref && idOf(r) === ref) return true;
  const p = digits(r.phone || r.phone_number || r.caller_phone);
  return phone.length >= 7 && p.length >= 7 && p.slice(-10) === phone.slice(-10);
});

if (!matches.length) return [{ json: { found: false } }];

matches.sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')));
const m = (ref && matches.find(r => idOf(r) === ref)) || matches[0];
const isTicket = ('ticket_id' in m) || ('issue_description' in m);
return [{ json: { found: true, type: isTicket ? 'ticket' : 'appointment', status: m.status || 'pending', datetime: m.datetime || '', reference: m.id || m.ticket_id || '' } }];

