// Finds the caller's active appointment and plans a cancel or reschedule.
const inp = $('Prepare Manage Data').first().json;
const digits = v => String(v ?? '').replace(/\D/g, '');
const samePhone = (a, b) => { a = digits(a); b = digits(b); return a.length >= 7 && b.length >= 7 && a.slice(-10) === b.slice(-10); };
const normTime = t => {
  const s = String(t ?? '').trim().toLowerCase().replace(/\./g, '');
  const m = s.match(/^(\d{1,2})(?::(\d{2}))?(?::\d{2})?\s*(am|pm)?$/);
  if (!m) return s;
  let h = parseInt(m[1], 10); const min = m[2] || '00';
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  return String(h).padStart(2, '0') + ':' + min;
};
const splitDT = dt => { const s = String(dt ?? '').trim().replace(/\s+/g, ' '); const i = s.indexOf(' '); return i === -1 ? [s, ''] : [s.slice(0, i), s.slice(i + 1)]; };
const slotKey = (d, t) => String(d ?? '').trim() + ' ' + normTime(t);
const inactive = s => ['cancelled', 'canceled', 'rescheduled'].includes(String(s ?? '').toLowerCase().trim());
const fail = (reason, message, extra = {}) => [{ json: { ok: false, reason, message, ...extra } }];

const action = inp.action === 'cancellation' ? 'cancel' : inp.action;
if (!['cancel', 'reschedule'].includes(action)) return fail('invalid_action', 'Would you like to cancel or reschedule your appointment?');

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const active = rows.filter(r => !inactive(r.status));
const ref = inp.appointment_id.toLowerCase();
let mine = active.filter(r => (ref && String(r.id).toLowerCase() === ref) || samePhone(r.phone, inp.phone_number));
if (ref) { const byId = mine.filter(r => String(r.id).toLowerCase() === ref); if (byId.length) mine = byId; }
if (inp.current_date && mine.length > 1) { const byDate = mine.filter(r => splitDT(r.datetime)[0] === inp.current_date); if (byDate.length) mine = byDate; }

if (!mine.length) return fail('not_found', "I couldn't find an active appointment under that phone number. Could you confirm the number you booked with?");
if (mine.length > 1) return fail('multiple', 'I found more than one appointment. Which date is the one you want to change: ' + mine.map(r => r.datetime).join(', ') + '?', { appointments: mine.map(r => ({ id: r.id, datetime: r.datetime, service: r.service })) });

const target = mine[0];
const stamp = new Date().toISOString();

if (action === 'cancel') {
  return [{ json: { ok: true, id: target.id, status: 'cancelled', datetime: target.datetime, notes: String(target.notes || '') + ' | Cancelled via call ' + inp.call_id + ' at ' + stamp, message: 'Your appointment on ' + target.datetime + ' has been cancelled.' } }];
}

if (!inp.new_date || !inp.new_time) return fail('missing_new_slot', 'What new date and time would you like?');
const newSlot = slotKey(inp.new_date, inp.new_time);
const clash = active.find(r => r.id !== target.id && (() => { const [d, t] = splitDT(r.datetime); return slotKey(d, t) === newSlot; })());
if (clash) return fail('slot_taken', 'Sorry, ' + newSlot + ' is already taken. Could you choose a different time?');

return [{ json: { ok: true, id: target.id, status: 'booked', datetime: newSlot, notes: String(target.notes || '') + ' | Rescheduled from ' + target.datetime + ' via call ' + inp.call_id + ' at ' + stamp, message: 'Your appointment has been moved to ' + newSlot + '.' } }];
